35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "title")
39	    private String title;
40	
41	    @Column(name = "address")
42	    private String address;
43	
44	    @Column(name = "address_line1")
45	    private String addressLine1;
46	
47	    @Column(name = "address_line2")
48	    private String addressLine2;
49	
50	    @Column(name = "city")
51	    @NotEmpty
52	    private String city;
53	
54	    @Column(name = "postcode")
55	    private String postcode;
56	
57	    @Column(name = "telephone")
58	    @NotEmpty
59	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Telephone must be in E.164 form (a '+' followed by 8 to 15 digits)")
60	    private String telephone;
61	
62	    @Column(name = "email")
63	    private String email;
64	
65	    @Column(name = "registration_date")
66	    private LocalDate registrationDate;
67	
68	    @Column(name = "birth_date")
69	    private LocalDate birthDate;
70	
71	    @Column(name = "member_id")
72	    private String memberId;
73	
74	    @Column(name = "household_id")
75	    private String householdId;
76	
77	    @Column(name = "namesake_count")
78	    private Integer namesakeCount;
79	
80	    @Column(name = "possible_duplicate")
81	    private Boolean possibleDuplicate;
82	
83	    @Column(name = "possible_duplicate_of")
84	    private Integer possibleDuplicateOf;
85	
86	    @Column(name = "deleted")
87	    private Boolean deleted = false;
88	
89	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
90	    private Set<Pet> pets;
91	
92	    public String getTitle() {
93	        return this.title;
94	    }
95	
96	    public void setTitle(String title) {
97	        this.title = title;
98	    }
99	
100	    public String getAddress() {
