115	
116	    public String getAddressLine2() {
117	        return this.addressLine2;
118	    }
119	
120	    public void setAddressLine2(String addressLine2) {
121	        this.addressLine2 = addressLine2;
122	    }
123	
124	    public String getCity() {
125	        return this.city;
126	    }
127	
128	    public void setCity(String city) {
129	        this.city = city;
130	    }
131	
132	    public String getTelephone() {
133	        return this.telephone;
134	    }
135	
136	    public void setTelephone(String telephone) {
