74	/**
75	 * @author Vitaliy Fedoriv
76	 */
77	
78	@RestController
79	@CrossOrigin(exposedHeaders = "errors, content-type")
80	@RequestMapping("/api")
81	public class OwnerRestControllerV1 implements OwnersApi {
82	
83	    /**
84	     * Matches a syntactically valid email: a non-empty local part and domain separated by a single
85	     * '@', with at least one dot-separated label in the domain and no whitespace anywhere.
86	     */
87	    private static final Pattern EMAIL_PATTERN =
88	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
89	
90	    /**
91	     * Email domains rejected as disposable/throwaway addresses. An owner whose email domain matches
92	     * one of these (compared case-insensitively) is rejected with 400.
93	     */
94	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
95	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
96	
97	    /**
98	     * Dedicated audit logger. On a successful owner create an audit line is emitted carrying the
99	     * new owner's id, memberId, registrationDate and membershipLevel, followed by an immutable
100	     * structured {@link OwnerCreatedEvent} serialized as JSON.
101	     */
102	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
103	
104	    /**
105	     * Dedicated logger for the welcome notification enqueued on a successful owner create. Each event
106	     * carries the new owner's id and its assigned {@code memberId}, so a downstream notifier can key
107	     * the welcome off the owner's canonical identity.
108	     */
109	    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");
110	
111	    /**
112	     * Source of the {@code seq} carried by each {@link OwnerCreatedEvent}: a monotonically increasing
113	     * integer allocated once per successful owner create, so the structured events form an ordered,
114	     * gap-free sequence within the running application.
115	     */
116	    private static final AtomicLong AUDIT_EVENT_SEQUENCE = new AtomicLong();
117	
118	    /**
119	     * Common street-type abbreviations expanded during address normalization, keyed by the
120	     * upper-cased abbreviation.
121	     */
122	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
123	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
124	
125	    /**
126	     * Maximum number of owners a single city may contain. A create is rejected once the owner's
127	     * city already holds this many owners.
128	     */
129	    private static final int CITY_CAPACITY = 50;
130	
131	    /**
132	     * Maximum number of owners that may be created on a single day. A create is rejected once this
133	     * many owners already carry the current day as their {@code registrationDate}.
134	     */
135	    private static final int DAILY_OWNER_LIMIT = 100;
136	
137	    /**
138	     * Fixed public holidays that the business-day roll skips: when an adjusted registration date lands
139	     * on one of these it advances to the next non-holiday business day.
140	     */
141	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
142	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
143	        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"), LocalDate.parse("2026-12-28"));
144	
145	    private final ClinicService clinicService;
146	
147	    private final OwnerMapper ownerMapper;
148	
149	    private final PetMapper petMapper;
150	
151	    private final VisitMapper visitMapper;
152	
153	    /**
154	     * Remembers the id of the owner created under each seen {@code Idempotency-Key}, so a create that
155	     * repeats with an already-seen key returns the originally created owner instead of creating a
156	     * duplicate.
157	     */
158	    private final Map<String, Integer> ownersByIdempotencyKey = new ConcurrentHashMap<>();
159	
160	    public OwnerRestControllerV1(ClinicService clinicService,
161	                                 OwnerMapper ownerMapper,
162	                                 PetMapper petMapper,
163	                                 VisitMapper visitMapper) {
164	        this.clinicService = clinicService;
165	        this.ownerMapper = ownerMapper;
166	        this.petMapper = petMapper;
167	        this.visitMapper = visitMapper;
168	    }
169	
170	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
171	    @Override
172	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
173	        Collection<Owner> owners;
174	        if (lastName != null) {
175	            owners = this.clinicService.findOwnerByLastName(lastName);
176	        } else {
177	            owners = this.clinicService.findAllOwners();
178	        }
179	        if (owners.isEmpty()) {
180	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
181	        }
182	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
183	    }
184	
185	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
186	    @Override
187	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
188	        Owner owner = this.clinicService.findOwnerById(ownerId);
189	        if (owner == null) {
190	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
191	        }
192	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
193	    }
194	
195	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
196	    @Override
197	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
198	        String idempotencyKey = currentIdempotencyKey();
199	        if (idempotencyKey != null) {
200	            Integer existingId = ownersByIdempotencyKey.get(idempotencyKey);
201	            if (existingId != null) {
202	                Owner existing = this.clinicService.findOwnerById(existingId);
203	                if (existing != null) {
204	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
205	                }
206	            }
207	        }
208	        validateRequiredFields(ownerFieldsDto);
209	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
210	        HttpHeaders headers = new HttpHeaders();
211	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
212	        applyAddress(owner, ownerFieldsDto);
213	        rejectFutureRegistrationDate(owner.getRegistrationDate());
214	        LocalDate effectiveDate = owner.getRegistrationDate() == null
215	            ? LocalDate.now()
216	            : owner.getRegistrationDate();
217	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
218	        rejectWhenDailyLimitReached(owner.getRegistrationDate());
219	        rejectWhenCityAtCapacity(owner.getCity());
220	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
221	        applyHousehold(owner);
222	        owner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
223	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
224	        rejectDuplicateIdentity(owner);
225	        owner.setMemberId(memberId(owner));
226	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
227	        flagPossibleDuplicate(owner, sharesHousehold);
228	        this.clinicService.saveOwner(owner);
229	        if (idempotencyKey != null) {
230	            ownersByIdempotencyKey.put(idempotencyKey, owner.getId());
231	        }
232	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
233	        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
234	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
235	            ownerDto.getMembershipLevel());
236	        String ownerSegment = ownerDto.getOwnerSegment() == null
237	            ? null
238	            : ownerDto.getOwnerSegment().getValue();
239	        OwnerCreatedEvent event = new OwnerCreatedEvent(AUDIT_EVENT_SEQUENCE.incrementAndGet(),
240	            owner.getId(), primaryIdentifier(owner), ownerDto.getMembershipLevel(), ownerSegment);
241	        AUDIT.info("{}", event.toJson());
242	        NOTIFY.info("welcome owner id={} memberId={}", owner.getId(), owner.getMemberId());
243	        headers.setLocation(UriComponentsBuilder.newInstance()
244	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
245	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
246	    }
247	
248	    /**
249	     * Reads the {@code Idempotency-Key} header of the request currently being handled, returning
250	     * {@code null} when the header is absent or blank (or there is no bound request). A non-blank
251	     * value opts the create into idempotent replay via {@link #ownersByIdempotencyKey}.
252	     *
253	     * @return the trimmed idempotency key, or {@code null} when none was supplied
254	     */
255	    private String currentIdempotencyKey() {
256	        if (!(RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attrs)) {
257	            return null;
258	        }
259	        String key = attrs.getRequest().getHeader("Idempotency-Key");
260	        return isBlank(key) ? null : key.trim();
261	    }
262	
263	    /**
264	     * Returns the owner's current primary identifier, the value carried by the {@link OwnerCreatedEvent}
265	     * so downstream consumers can key the create off the owner's canonical identity. An owner's primary
266	     * identifier is its unified {@code memberId}, and the emitted event follows automatically.
267	     *
268	     * @param owner the freshly created owner, with its identifiers already assigned
269	     * @return the owner's current primary identifier
270	     */
271	    private String primaryIdentifier(Owner owner) {
272	        return owner.getMemberId();
273	    }
274	
275	    /**
276	     * Builds the owner's unified member id, formatted {@code <REGION><FY><HASH8><CHK>}: REGION is the
277	     * version-2 {@link #identityRegionCode(Owner) identity region code} (the plain region code with
278	     * the fixed {@code 'V2'} version tag mixed in); FY is the 2-digit fiscal year of the owner's
279	     * business-day-adjusted registration date; HASH8 is the first 8 upper-cased hex characters of the
280	     * SHA-256 of the {@code 'V2'} version tag, the owner's normalized telephone and its last name; and
281	     * CHK is a single Luhn check digit computed over the digits of {@code <REGION><FY><HASH8>} (e.g.
282	     * {@code V2NSW261A2B3C4D3}).
283	     *
284	     * <p>Should the computed member id collide with an existing owner's {@code memberId}, it is
285	     * de-duplicated by appending {@code -<n>} with the smallest {@code n} of 2 or more that makes it
286	     * unique (e.g. {@code V2NSW261A2B3C4D3-2}), so distinct owners always receive distinct member ids.
287	     *
288	     * @param owner the owner being created, with its normalized telephone and business-day-adjusted
289	     *              registration date already applied
290	     * @return the assigned, de-duplicated member id
291	     */
292	    private String memberId(Owner owner) {
293	        String core = identityRegionCode(owner)
294	            + String.format("%02d", fiscalYear(owner.getRegistrationDate()) % 100)
295	            + identityHash8(owner.getTelephone(), owner.getLastName());
296	        String base = core + luhnCheckDigit(core);
297	        Set<String> existingIds = this.clinicService.findAllOwners().stream()
298	            .map(Owner::getMemberId)
299	            .filter(id -> id != null)
300	            .collect(java.util.stream.Collectors.toSet());
301	        if (!existingIds.contains(base)) {
302	            return base;
303	        }
304	        int n = 2;
305	        while (existingIds.contains(base + "-" + n)) {
306	            n++;
307	        }
308	        return base + "-" + n;
309	    }
