311	    /**
312	     * Computes the Luhn check digit (a single digit 0-9) over the digits contained in the given value.
313	     * Non-digit characters are ignored.
314	     *
315	     * @param value the value whose digits the check digit is computed over
316	     * @return the Luhn check digit
317	     */
318	    private int luhnCheckDigit(String value) {
319	        int sum = 0;
320	        boolean dbl = true;
321	        for (int i = value.length() - 1; i >= 0; i--) {
322	            char c = value.charAt(i);
323	            if (c < '0' || c > '9') {
324	                continue;
325	            }
326	            int d = c - '0';
327	            if (dbl) {
328	                d *= 2;
329	                if (d > 9) {
330	                    d -= 9;
331	                }
332	            }
333	            sum += d;
334	            dbl = !dbl;
335	        }
336	        return (10 - (sum % 10)) % 10;
337	    }
