346	     * @param owner the owner being created
347	     * @return the derived region code, never {@code null}
348	     */
349	    private String regionCode(Owner owner) {
350	        String fromPostcode = regionFromPostcode(owner.getPostcode());
351	        if (fromPostcode != null) {
352	            return fromPostcode;
