358	    /**
359	     * Derives the version-2 region code embedded inside an owner's {@code memberId}: the plain
360	     * {@link #regionCode(Owner) region code} with the fixed {@code 'V2'} version tag mixed in
361	     * (e.g. {@code NSW} becomes {@code V2NSW}). This is the region code used <em>inside</em> the
362	     * identifier only; the user-facing {@code locality}, {@code timezone} and owner-segment region
363	     * keep the plain region code, so the {@code 'V2'} tag never leaks into them.
364	     *
365	     * @param owner the owner being created
366	     * @return the version-2 identity region code, never {@code null}
367	     */
368	    private String identityRegionCode(Owner owner) {
369	        return IdentityKeys.VERSION_TAG + regionCode(owner);
370	    }
