372	    /**
373	     * Resolves the region whose postcode range contains the given postcode, or {@code null} when the
374	     * postcode is absent, not 4 digits, or in no known range.
375	     *
376	     * @param postcode the owner's postcode, may be {@code null}
377	     * @return the region code, or {@code null} when no known range contains the postcode
378	     */
379	    private String regionFromPostcode(String postcode) {
380	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
381	            return null;
382	        }
383	        int value = Integer.parseInt(postcode);
384	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
385	            int[] range = entry.getValue();
386	            if (value >= range[0] && value <= range[1]) {
387	                return entry.getKey();
388	            }
389	        }
390	        return null;
391	    }
