393	    /**
394	     * Computes the identity hash embedded in an owner's customer code: the first 8 upper-cased hex
395	     * characters of the SHA-256 of the fixed {@code 'V2'} version tag, the owner's normalized
396	     * telephone and its last name. Mixing in the version tag is what moves the hash to version 2, so
397	     * no value produced under version 1 is produced again.
398	     *
399	     * @param telephone the owner's normalized (E.164) telephone
400	     * @param lastName  the owner's last name
401	     * @return the 8-character upper-cased hex hash
402	     */
403	    private String identityHash8(String telephone, String lastName) {
404	        String input = IdentityKeys.VERSION_TAG + "|"
405	            + (telephone == null ? "" : telephone) + (lastName == null ? "" : lastName);
406	        try {
407	            byte[] digest = MessageDigest.getInstance("SHA-256")
408	                .digest(input.getBytes(StandardCharsets.UTF_8));
409	            StringBuilder hex = new StringBuilder(digest.length * 2);
410	            for (byte b : digest) {
411	                hex.append(String.format("%02x", b));
412	            }
413	            return hex.substring(0, 8).toUpperCase(Locale.ROOT);
414	        } catch (NoSuchAlgorithmException ex) {
415	            throw new IllegalStateException("SHA-256 not available", ex);
416	        }
417	    }
