452	    /**
453	     * Flags an owner as a possible (soft) duplicate. Although it is not a hard duplicate (its whole
454	     * {@link #identityKey(Owner) identityKey} is unique, so the create was not rejected), it may
455	     * still resemble an existing owner: when it shares an existing owner's {@code soundex(lastName)}
456	     * and postcode while deriving a different identityKey, the owner is flagged with
457	     * {@code possibleDuplicate=true} and {@code possibleDuplicateOf} set to that existing owner's id.
458	     * When no such owner exists the flag is set to {@code false} and no match id is recorded. An
459	     * owner with no postcode can never soft-match and is always {@code false}.
460	     *
461	     * <p>A declared household member (created with {@code sharesHousehold=true}) is never a suspected
462	     * duplicate: its match with an existing household member is a deliberate, declared one, so it is
463	     * always flagged {@code false}.
464	     *
465	     * @param owner           the owner being created, with its normalized telephone already applied
466	     * @param sharesHousehold whether the request declared it shares a household; a declared member is
467	     *                        never flagged as a possible duplicate
468	     */
469	    private void flagPossibleDuplicate(Owner owner, boolean sharesHousehold) {
470	        Owner match = sharesHousehold ? null : findPossibleDuplicate(owner);
471	        if (match != null) {
472	            owner.setPossibleDuplicate(true);
473	            owner.setPossibleDuplicateOf(match.getId());
474	        } else {
475	            owner.setPossibleDuplicate(false);
476	            owner.setPossibleDuplicateOf(null);
477	        }
478	    }
