480	    /**
481	     * Finds the existing owner this owner soft-matches: a different {@link #identityKey(Owner)
482	     * identityKey} but the same {@code soundex(lastName)} and the same postcode. Because the
483	     * telephone now feeds the identityKey, two owners sharing a lastName and postcode with different
484	     * telephones have different keys and so soft-match here rather than being rejected as a hard
485	     * duplicate. When several existing owners match, the one with the lowest id is chosen so the
486	     * result is deterministic. Returns {@code null} when the owner has no postcode or no such
487	     * existing owner exists.
488	     *
489	     * @param owner the owner being created
490	     * @return the matching existing owner, or {@code null} when there is no soft-match
491	     */
492	    private Owner findPossibleDuplicate(Owner owner) {
493	        if (isBlank(owner.getPostcode())) {
494	            return null;
495	        }
496	        String identityKey = identityKey(owner);
497	        String soundex = IdentityKeys.soundex(owner.getLastName());
498	        return this.clinicService.findAllOwners().stream()
499	            .filter(existing -> !identityKey.equals(identityKey(existing))
500	                && soundex.equals(IdentityKeys.soundex(existing.getLastName()))
501	                && owner.getPostcode().equals(existing.getPostcode()))
502	            .min(Comparator.comparing(Owner::getId))
503	            .orElse(null);
504	    }
