556	    /**
557	     * Rolls a registration date forward onto a business day: while it falls on a Saturday, a Sunday or
558	     * a listed {@link #PUBLIC_HOLIDAYS public holiday} it advances one day at a time until it lands on
559	     * a non-holiday weekday, otherwise it is returned unchanged. Applied to the effective registration
560	     * date (whether supplied in the request or defaulted to the server date) so a weekend or holiday
561	     * value never persists as an owner's {@code registrationDate}.
562	     *
563	     * @param date the effective registration date
564	     * @return the same date when it is a non-holiday weekday, otherwise the next non-holiday business day
565	     */
566	    private LocalDate toBusinessDay(LocalDate date) {
567	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
568	            || date.getDayOfWeek() == DayOfWeek.SUNDAY
569	            || PUBLIC_HOLIDAYS.contains(date)) {
570	            date = date.plusDays(1);
571	        }
572	        return date;
573	    }
