640	    /**
641	     * Validates an owner's postcode, but only when one is supplied. A {@code null} or blank postcode
642	     * is optional and accepted, keeping the create contract backward-compatible. When present the
643	     * value must be 4 digits and, when the owner's city has a known region (Sydney->NSW,
644	     * Melbourne->VIC, Brisbane->QLD), must fall within that region's inclusive range (NSW 2000-2099,
645	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
646	     *
647	     * @param postcode the raw postcode value as submitted, may be {@code null}
648	     * @param city     the owner's city, used to resolve the region whose range applies
649	     * @throws InvalidPostcodeException if a supplied postcode is not 4 digits or is out of range for
650	     *                                  the city's region
651	     */
652	    private void validatePostcode(String postcode, String city) {
653	        if (isBlank(postcode)) {
654	            return;
655	        }
656	        if (!postcode.matches("[0-9]{4}")) {
657	            throw new InvalidPostcodeException(postcode, city);
658	        }
659	        String region = region(city);
660	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
661	        if (range != null) {
662	            int value = Integer.parseInt(postcode);
663	            if (value < range[0] || value > range[1]) {
664	                throw new InvalidPostcodeException(postcode, city);
665	            }
666	        }
667	    }
