669	    /**
670	     * Derives an owner's region from its city using the fixed city-to-region table (Sydney->NSW,
671	     * Melbourne->VIC, Brisbane->QLD), returning {@code null} when the city is not in the table.
672	     *
673	     * @param city the owner's city
674	     * @return the region code, or {@code null} when the city has no known region
675	     */
676	    private String region(String city) {
677	        if (city == null) {
678	            return null;
679	        }
680	        return switch (city) {
681	            case "Sydney" -> "NSW";
682	            case "Melbourne" -> "VIC";
683	            case "Brisbane" -> "QLD";
684	            default -> null;
685	        };
