688	    /**
689	     * The number of national (subscriber) digits an E.164 number must carry for a given country
690	     * calling code, keyed by that code (without the leading '+'). Australia ('+61') requires 9
691	     * national digits and the North American Numbering Plan ('+1') requires 10.
692	     */
693	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
694	        Map.of("61", 9, "1", 10);
695	
696	    /**
697	     * Normalizes a submitted telephone into E.164 form. Spaces, dashes and brackets are stripped.
698	     * A leading '+' with its country code is kept; otherwise the country code '+61' is assumed and
699	     * a single leading '0' is dropped from the national digits. The resulting value must be a '+'
700	     * followed by 8 to 15 digits, and its national-number length must match the one required by its
701	     * country calling code ('+61' requires 9 national digits, '+1' requires 10).
702	     *
703	     * @param telephone the raw telephone value as submitted
704	     * @return the E.164 normalized telephone (e.g. {@code +61412345678})
705	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number, or its
706	     *                                   national-number length is wrong for its country code
707	     */
708	    private String normalizeTelephone(String telephone) {
709	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
710	        String nationalSignificantNumber;
711	        if (cleaned.startsWith("+")) {
712	            nationalSignificantNumber = cleaned.substring(1);
713	        } else {
714	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
715	            nationalSignificantNumber = "61" + national;
716	        }
717	        if (!nationalSignificantNumber.matches("[0-9]{8,15}")) {
718	            throw new InvalidTelephoneException(telephone);
719	        }
720	        validateNationalNumberLength(nationalSignificantNumber, telephone);
721	        return "+" + nationalSignificantNumber;
722	    }
723	
724	    /**
725	     * Validates the national-number length of an E.164 number against its country calling code. The
726	     * significant number is a country code immediately followed by the national digits; for each
727	     * known code in {@link #NATIONAL_NUMBER_LENGTHS} the remaining national digits must number
728	     * exactly the required amount ('+61' requires 9, '+1' requires 10). Codes with no known rule are
729	     * left unchecked.
730	     *
731	     * @param nationalSignificantNumber the E.164 digits following the '+' (country code + national)
732	     * @param rejectedValue             the raw telephone value, reported on rejection
733	     * @throws InvalidTelephoneException if the national-number length is wrong for the country code
734	     */
735	    private void validateNationalNumberLength(String nationalSignificantNumber, String rejectedValue) {
736	        for (Map.Entry<String, Integer> rule : NATIONAL_NUMBER_LENGTHS.entrySet()) {
737	            String countryCode = rule.getKey();
738	            if (nationalSignificantNumber.startsWith(countryCode)) {
739	                int nationalDigits = nationalSignificantNumber.length() - countryCode.length();
740	                if (nationalDigits != rule.getValue()) {
741	                    throw new InvalidTelephoneException(rejectedValue);
742	                }
743	                return;
744	            }
745	        }
746	    }
