748	    /**
749	     * Normalizes a submitted email. An owner may omit the email entirely (a {@code null} or blank
750	     * value is treated as absent and returns {@code null}); when present the value must be a
751	     * syntactically valid address, and is stored and returned lower-cased.
752	     *
753	     * @param email the raw email value as submitted, may be {@code null}
754	     * @return the lower-cased email, or {@code null} when none was supplied
755	     * @throws InvalidEmailException if a non-blank value is not a syntactically valid address
756	     */
757	    private String normalizeEmail(String email) {
758	        if (email == null || email.isBlank()) {
759	            return null;
760	        }
761	        String normalized = email.trim().toLowerCase();
762	        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
763	            throw new InvalidEmailException(email);
764	        }
765	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
766	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
767	            throw new DisposableEmailException(email);
768	        }
769	        return normalized;
770	    }
