825	    /**
826	     * Derives the stable, shared household identifier for an owner, formatted {@code HH-<HEX12>}
827	     * where HEX12 is the first 12 upper-cased hex characters of the SHA-256 of the fixed {@code 'V2'}
828	     * version tag, the owner's normalized lastName and its postcode, joined with {@code '|'}
829	     * separators. Being a pure function of (lastName, postcode), every owner sharing a lastName and
830	     * postcode derives the same value regardless of creation order. A {@code null} postcode
831	     * contributes an empty segment. Mixing in the version tag moves the identifier to version 2, so
832	     * no value produced under version 1 is produced again.
833	     *
834	     * @param owner the owner whose household identifier to derive
835	     * @return the household identifier
836	     */
837	    private String householdId(Owner owner) {
838	        String lastNameKey = toHouseholdKey(owner.getLastName());
839	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
840	        try {
841	            byte[] digest = MessageDigest.getInstance("SHA-256")
842	                .digest((IdentityKeys.VERSION_TAG + "|" + lastNameKey + "|" + postcode)
843	                    .getBytes(StandardCharsets.UTF_8));
844	            StringBuilder hex = new StringBuilder(digest.length * 2);
845	            for (byte b : digest) {
846	                hex.append(String.format("%02x", b));
847	            }
848	            return "HH-" + hex.substring(0, 12).toUpperCase(Locale.ROOT);
849	        } catch (NoSuchAlgorithmException ex) {
850	            throw new IllegalStateException("SHA-256 not available", ex);
851	        }
852	    }
