867	    /**
868	     * Applies the owner's address, preferring the structured form over the flat one. The structured
869	     * {@code addressLine1}/{@code addressLine2} and the flat {@code address} are each normalized (see
870	     * {@link #normalizeAddress(String)}). When a non-blank {@code addressLine1} is supplied the
871	     * structured form wins: {@code addressLine1} and {@code addressLine2} are stored normalized (a
872	     * blank {@code addressLine2} is stored as {@code null}), and the composed {@code address} is the
873	     * normalized {@code addressLine1} with a single space and the normalized {@code addressLine2}
874	     * appended when an {@code addressLine2} is present. Otherwise the flat {@code address} is used for
875	     * backward compatibility: the normalized flat value becomes both {@code addressLine1} and the
876	     * stored {@code address}, with no {@code addressLine2}. Everything that later reads the owner's
877	     * address therefore sees the structured value when present, falling back to the flat one.
878	     *
879	     * @param owner the owner being created
880	     * @param dto   the submitted owner fields
881	     */
882	    private void applyAddress(Owner owner, OwnerFieldsDto dto) {
883	        String line1 = normalizeAddress(dto.getAddressLine1());
884	        String line2 = normalizeAddress(dto.getAddressLine2());
885	        String flat = normalizeAddress(dto.getAddress());
886	        String effectiveLine1 = line1.isEmpty() ? flat : line1;
887	        String effectiveLine2 = line1.isEmpty() ? "" : line2;
888	        String composed = effectiveLine2.isEmpty()
889	            ? effectiveLine1
890	            : effectiveLine1 + " " + effectiveLine2;
891	        owner.setAddressLine1(effectiveLine1.isEmpty() ? null : effectiveLine1);
892	        owner.setAddressLine2(effectiveLine2.isEmpty() ? null : effectiveLine2);
893	        owner.setAddress(composed);
894	    }
