896	    /**
897	     * Normalizes a submitted address into the canonical form stored and returned for an owner:
898	     * leading and trailing whitespace is trimmed, internal runs of whitespace are collapsed to a
899	     * single space, the value is upper-cased, and common street-type abbreviations are expanded on a
900	     * whole-word basis ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null}
901	     * value, or one that is blank once trimmed, normalizes to an empty string.
902	     *
903	     * @param address the raw address value as submitted, may be {@code null}
904	     * @return the normalized address, or an empty string when none was supplied
905	     */
906	    private String normalizeAddress(String address) {
907	        if (address == null) {
908	            return "";
909	        }
910	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
911	        if (collapsed.isEmpty()) {
912	            return "";
913	        }
914	        String[] tokens = collapsed.split(" ");
915	        StringBuilder normalized = new StringBuilder(collapsed.length());
916	        for (int i = 0; i < tokens.length; i++) {
917	            if (i > 0) {
918	                normalized.append(' ');
919	            }
920	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
921	        }
922	        return normalized.toString();
923	    }
