1021	     * Immutable structured audit event emitted alongside the human-readable audit line on a successful
1022	     * owner create. It is a schema-version-2 event: it records its {@code schemaVersion}, the create's
1023	     * monotonic {@code seq}, the new owner's id, the owner's current primary identifier, its membership
1024	     * level and its owner segment recomputed from the version-2 identity, plus a fixed
1025	     * {@code OWNER_CREATED} marker.
1026	     *
1027	     * <p>The primary identifier is serialized under the {@code memberId} key, matching the owner's
1028	     * unified primary identifier.
1029	     */
1030	    private record OwnerCreatedEvent(long seq, Integer ownerId, String memberId,
1031	                                     Integer membershipLevel, String ownerSegment) {
1032	
1033	        private static final String EVENT = "OWNER_CREATED";
1034	
1035	        /**
1036	         * The audit event schema version. Version 2 adds the {@code schemaVersion} field itself and
1037	         * the {@code ownerSegment} recomputed from the version-2 identity.
1038	         */
1039	        private static final int SCHEMA_VERSION = 2;
1040	
1041	        /**
1042	         * Renders the event as a compact JSON object {@code {"schemaVersion":2,"seq":..,"ownerId":..,
1043	         * "memberId":..,"membershipLevel":..,"ownerSegment":..,"event":"OWNER_CREATED"}}.
1044	         */
1045	        String toJson() {
1046	            StringBuilder json = new StringBuilder(128);
1047	            json.append('{')
1048	                .append("\"schemaVersion\":").append(SCHEMA_VERSION)
1049	                .append(",\"seq\":").append(this.seq)
1050	                .append(",\"ownerId\":").append(this.ownerId)
1051	                .append(",\"memberId\":").append(jsonString(this.memberId))
1052	                .append(",\"membershipLevel\":").append(this.membershipLevel)
1053	                .append(",\"ownerSegment\":").append(jsonString(this.ownerSegment))
1054	                .append(",\"event\":").append(jsonString(EVENT))
1055	                .append('}');
1056	            return json.toString();
1057	        }
1058	
1059	        /**
1060	         * Renders a nullable string as a JSON literal: {@code null} when absent, otherwise a
1061	         * double-quoted, minimally-escaped string.
1062	         */
1063	        private static String jsonString(String value) {
1064	            if (value == null) {
1065	                return "null";
1066	            }
1067	            StringBuilder out = new StringBuilder(value.length() + 2);
1068	            out.append('"');
1069	            for (int i = 0; i < value.length(); i++) {
1070	                char c = value.charAt(i);
1071	                switch (c) {
1072	                    case '"' -> out.append("\\\"");
1073	                    case '\\' -> out.append("\\\\");
1074	                    case '\n' -> out.append("\\n");
1075	                    case '\r' -> out.append("\\r");
1076	                    case '\t' -> out.append("\\t");
1077	                    default -> {
1078	                        if (c < 0x20) {
1079	                            out.append(String.format("\\u%04x", (int) c));
1080	                        } else {
1081	                            out.append(c);
1082	                        }
1083	                    }
1084	                }
1085	            }
1086	            out.append('"');
1087	            return out.toString();
1088	        }
1089	    }
