169	    /**
170	     * Derives the owner's {@code ageBand} from their {@code birthDate} relative to their
171	     * {@code registrationDate}: {@code MINOR} when under 18, {@code ADULT} from 18 to 64, and
172	     * {@code SENIOR} at 65 or older. Returns {@code null} when no birth date was supplied, or when
173	     * the registration date (against which the age is measured) is absent.
174	     */
175	    protected OwnerDto.AgeBandEnum ageBand(Owner owner) {
176	        LocalDate birthDate = owner.getBirthDate();
177	        LocalDate registrationDate = owner.getRegistrationDate();
178	        if (birthDate == null || registrationDate == null) {
179	            return null;
180	        }
181	        int age = Period.between(birthDate, registrationDate).getYears();
182	        if (age < 18) {
183	            return OwnerDto.AgeBandEnum.MINOR;
184	        }
185	        if (age < 65) {
186	            return OwnerDto.AgeBandEnum.ADULT;
187	        }
188	        return OwnerDto.AgeBandEnum.SENIOR;
189	    }
190	
191	    /**
192	     * The country calling codes (without the leading {@code '+'}) the display formatter recognises,
193	     * longest first so the correct code is matched before a shorter prefix of it. Australia
194	     * ({@code +61}) and the North American Numbering Plan ({@code +1}) mirror the codes the create
195	     * endpoint normalizes against.
196	     */
197	    private static final List<String> KNOWN_COUNTRY_CODES = List.of("61", "1");
198	
199	    /**
200	     * Derives the owner's {@code telephoneDisplay}: the stored E.164 {@code telephone} formatted for
201	     * humans as the country code, a space, then the national digits grouped in threes (e.g.
202	     * {@code +61412345678} becomes {@code +61 412 345 678}). Returns the raw value unchanged when it
203	     * is {@code null} or not an E.164 number ({@code '+'} followed by digits).
204	     */
205	    protected String telephoneDisplay(Owner owner) {
206	        String telephone = owner.getTelephone();
207	        if (telephone == null || !telephone.matches("\\+[0-9]+")) {
208	            return telephone;
209	        }
210	        String digits = telephone.substring(1);
211	        String countryCode = KNOWN_COUNTRY_CODES.stream()
212	            .filter(digits::startsWith)
213	            .findFirst()
214	            .orElse("");
215	        String national = digits.substring(countryCode.length());
216	        StringBuilder grouped = new StringBuilder();
217	        for (int i = 0; i < national.length(); i++) {
218	            if (i > 0 && i % 3 == 0) {
219	                grouped.append(' ');
220	            }
221	            grouped.append(national.charAt(i));
222	        }
223	        return "+" + countryCode + " " + grouped;
224	    }
225	
226	    /**
227	     * Derives the owner's {@code identityKey}, the single consolidated duplicate-detection key: the
228	     * lower-case hex SHA-256 of {@code "V2" + '|' + normalizedTelephone + '|' + lowerEmail + '|' +
229	     * soundex(lastName)}. A {@code null} telephone or email contributes an empty segment; the leading
230	     * {@code 'V2'} version tag is the version-2 identity marker.
231	     */
232	    protected String identityKey(Owner owner) {
233	        return IdentityKeys.identityKey(owner.getTelephone(), owner.getEmail(), owner.getLastName());
234	    }
