236	    /**
237	     * Derives the owner's preferred contact channel: {@code EMAIL} when an email address is
238	     * present, otherwise {@code PHONE}.
239	     */
240	    protected OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
241	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
242	        return hasEmail ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
243	    }
244	
245	    /**
246	     * The inclusive 4-digit postcode range that identifies each region, keyed by region code
247	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
248	     */
249	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
250	        "NSW", new int[] {2000, 2099},
251	        "VIC", new int[] {3000, 3099},
252	        "QLD", new int[] {4000, 4099});
253	
254	    /**
255	     * Derives the owner's plain locality (region) directly, preferring the postcode: a 4-digit
256	     * postcode falling in a known region's range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099)
257	     * yields that region, otherwise the city-to-region table (Sydney->NSW, Melbourne->VIC,
258	     * Brisbane->QLD) is consulted, returning {@code UNKNOWN} when neither identifies a region.
259	     *
260	     * <p>The locality is a user-facing field, not an identifier, so it stays the plain region code
261	     * (e.g. {@code NSW}); the version-2 {@code 'V2'} tag mixed into the {@code identity} identifiers
262	     * (memberId, householdId, identityKey) never appears here.
263	     */
264	    protected String locality(Owner owner) {
265	        String fromPostcode = regionFromPostcode(owner.getPostcode());
266	        if (fromPostcode != null) {
267	            return fromPostcode;
268	        }
269	        String city = owner.getCity();
270	        if (city == null) {
271	            return "UNKNOWN";
272	        }
273	        return switch (city) {
274	            case "Sydney" -> "NSW";
275	            case "Melbourne" -> "VIC";
276	            case "Brisbane" -> "QLD";
277	            default -> "UNKNOWN";
278	        };
279	    }
280	
281	    /**
282	     * The IANA timezone of each region, keyed by region code (NSW->Australia/Sydney,
283	     * VIC->Australia/Melbourne, QLD->Australia/Brisbane).
284	     */
285	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
286	        "NSW", "Australia/Sydney",
287	        "VIC", "Australia/Melbourne",
288	        "QLD", "Australia/Brisbane");
289	
290	    /**
291	     * Derives the owner's {@code timezone}: the IANA timezone name for the owner's
292	     * {@link #locality(Owner) locality/region}, looked up in the fixed region-to-timezone table
293	     * (NSW->Australia/Sydney, VIC->Australia/Melbourne, QLD->Australia/Brisbane). Returns
294	     * {@code null} when the region has no known timezone (e.g. {@code UNKNOWN}).
295	     */
296	    protected String timezone(Owner owner) {
297	        return REGION_TIMEZONE.get(locality(owner));
298	    }
299	
300	    /**
301	     * Resolves the region whose postcode range contains the given postcode, or {@code null} when
302	     * the postcode is absent, not 4 digits, or in no known range.
303	     */
304	    private String regionFromPostcode(String postcode) {
305	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
306	            return null;
307	        }
308	        int value = Integer.parseInt(postcode);
309	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
310	            int[] range = entry.getValue();
311	            if (value >= range[0] && value <= range[1]) {
312	                return entry.getKey();
313	            }
314	        }
315	        return null;
316	    }
317	
318	    /**
319	     * The minimum {@link #membershipLevel(Owner) membership level} at which an owner is a
320	     * {@code PREMIUM} tier for {@link #ownerSegment(Owner) segmentation}; below it the owner is
321	     * {@code STANDARD}.
322	     */
323	    private static final int PREMIUM_TIER_MIN_LEVEL = 3;
324	
325	    /**
326	     * The regions treated as {@code METRO} for {@link #ownerSegment(Owner) segmentation}; any other
327	     * locality (e.g. {@code UNKNOWN}) is {@code REGIONAL}.
328	     */
329	    private static final java.util.Set<String> METRO_REGIONS = java.util.Set.of("NSW", "VIC", "QLD");
330	
331	    /**
332	     * Derives the owner's {@code ownerSegment}, formatted {@code <TIER>_<AREA>} (one of
333	     * {@code PREMIUM_METRO}, {@code PREMIUM_REGIONAL}, {@code STANDARD_METRO} or
334	     * {@code STANDARD_REGIONAL}). TIER is {@code PREMIUM} when the owner's
335	     * {@link #membershipLevel(Owner) membership level} is {@value #PREMIUM_TIER_MIN_LEVEL} or more,
336	     * otherwise {@code STANDARD}. AREA is {@code METRO} when the owner's
337	     * {@link #locality(Owner) locality} is a known region (NSW, VIC or QLD), otherwise
338	     * {@code REGIONAL}.
339	     */
340	    protected OwnerDto.OwnerSegmentEnum ownerSegment(Owner owner) {
341	        String tier = membershipLevel(owner) >= PREMIUM_TIER_MIN_LEVEL ? "PREMIUM" : "STANDARD";
342	        String area = METRO_REGIONS.contains(locality(owner)) ? "METRO" : "REGIONAL";
343	        return OwnerDto.OwnerSegmentEnum.fromValue(tier + "_" + area);
344	    }
345	
346	    /**
347	     * The minimum household size (counting the owner itself) that earns household membership
348	     * points.
349	     */
350	    private static final int HOUSEHOLD_POINTS_SIZE = 3;
351	
352	    /**
353	     * An owner's tenure must span strictly more than this many elapsed fiscal years to earn the
354	     * tenure membership points. A newly created owner has zero elapsed fiscal years and so never
355	     * clears this threshold.
356	     */
357	    private static final int TENURE_POINTS_FISCAL_YEARS = 1;
358	
359	    /**
360	     * Derives the owner's membership points: it starts at 0, gains 2 when an email is present,
361	     * gains 1 when the owner has no namesakes (namesakeCount is 0), gains 2 when the owner's
362	     * household has {@value #HOUSEHOLD_POINTS_SIZE} or more members, and gains 3 once the owner's
363	     * tenure exceeds {@value #TENURE_POINTS_FISCAL_YEARS} elapsed fiscal year(s).
364	     */
365	    protected Integer membershipPoints(Owner owner) {
366	        int points = 0;
367	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
368	        if (hasEmail) {
369	            points += 2;
370	        }
371	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
372	        if (noNamesakes) {
373	            points += 1;
374	        }
375	        if (householdSize(owner) >= HOUSEHOLD_POINTS_SIZE) {
376	            points += 2;
377	        }
378	        if (tenureFiscalYears(owner) > TENURE_POINTS_FISCAL_YEARS) {
379	            points += 3;
380	        }
381	        return points;
382	    }
383	
384	    /**
385	     * Derives the owner's membership level, capped by their household. The level starts from the
386	     * owner's own {@link #uncappedMembershipLevel(Owner) points-based level} but may not exceed one
387	     * above the current maximum level among the owner's existing household members (other owners
388	     * sharing its {@code householdId}). When the owner has no existing household member no cap
389	     * applies and the points-based level is returned unchanged.
390	     */
391	    protected Integer membershipLevel(Owner owner) {
392	        int level = uncappedMembershipLevel(owner);
393	        OptionalInt maxHouseholdLevel = otherHouseholdMembers(owner)
394	            .mapToInt(this::uncappedMembershipLevel)
395	            .max();
396	        if (maxHouseholdLevel.isEmpty()) {
397	            return level;
398	        }
399	        return Math.min(level, maxHouseholdLevel.getAsInt() + 1);
400	    }
401	
402	    /**
403	     * The owner's points-based membership level, before the household ceiling is applied: level 1
404	     * for 0-1 points, level 2 for 2-3, level 3 for 4-5, and level 4 for 6 or more (see
405	     * {@link #membershipPoints(Owner) membership points}). The household members' maximum against
406	     * which {@link #membershipLevel(Owner)} caps is measured with this uncapped value, so mutual
407	     * household members do not recurse into each other's caps.
408	     */
409	    private int uncappedMembershipLevel(Owner owner) {
410	        int points = membershipPoints(owner);
411	        if (points <= 1) {
412	            return 1;
413	        }
414	        if (points <= 3) {
415	            return 2;
416	        }
417	        if (points <= 5) {
418	            return 3;
419	        }
420	        return 4;
421	    }
422	
423	    /**
424	     * The owner's existing household members: every other owner (excluding the owner itself) sharing
425	     * its {@code householdId}. Empty when the owner has no household identifier or is the sole member
426	     * of its household.
427	     */
428	    private Stream<Owner> otherHouseholdMembers(Owner owner) {
429	        String householdId = owner.getHouseholdId();
430	        if (householdId == null) {
431	            return Stream.empty();
432	        }
433	        return this.clinicService.findAllOwners().stream()
434	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
435	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()));
436	    }
437	
438	    /**
439	     * The number of owners in this owner's household — the count of owners (including this one)
440	     * sharing its {@code householdId}. Returns 0 when the owner has no household identifier.
441	     */
442	    private long householdSize(Owner owner) {
443	        String householdId = owner.getHouseholdId();
444	        if (householdId == null) {
445	            return 0;
446	        }
447	        return this.clinicService.findAllOwners().stream()
448	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
449	            .count();
450	    }
451	
452	    /**
453	     * The owner's tenure in elapsed fiscal years: the number of fiscal years (each starting 1 July)
454	     * between their {@code registrationDate} and the current date, i.e. the current fiscal year less
455	     * the registration date's fiscal year. Returns 0 when no registration date is present, so an
456	     * owner without a registration date is treated as having no tenure.
457	     */
458	    private long tenureFiscalYears(Owner owner) {
459	        LocalDate registrationDate = owner.getRegistrationDate();
460	        if (registrationDate == null) {
461	            return 0;
462	        }
463	        return (long) fiscalYearOf(LocalDate.now()) - fiscalYearOf(registrationDate);
464	    }
465	
466	    /**
467	     * Flags a bulk-signup day: {@code true} once more than {@link #BULK_SIGNUP_THRESHOLD} other
468	     * owners already carry this owner's {@code registrationDate}. The owner itself is excluded from
469	     * the count, so on a create the flag reflects the owners that pre-existed it that day, matching
470	     * the accumulation the per-day create limit is enforced against. Returns {@code false} when the
471	     * owner has no registration date.
472	     */
473	    protected Boolean bulkSignupWarning(Owner owner) {
474	        LocalDate registrationDate = owner.getRegistrationDate();
475	        if (registrationDate == null) {
476	            return false;
477	        }
478	        long othersOnDay = this.clinicService.findAllOwners().stream()
479	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
480	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
481	            .count();
482	        return othersOnDay > BULK_SIGNUP_THRESHOLD;
483	    }
484	
485	    /**
486	     * Flags a city approaching its hard capacity limit: {@code true} when this owner's city already
487	     * holds between {@link #CAPACITY_WARNING_THRESHOLD} and {@link #CITY_CAPACITY} minus one owners,
488	     * inclusive (excluding the owner itself), so on a create the flag reflects the owners that
489	     * pre-existed it in that city, matching the count the per-city capacity limit is enforced
490	     * against. Cities are compared case-insensitively, as they are for the capacity limit. Returns
491	     * {@code false} when the owner has no city.
492	     */
493	    protected Boolean capacityWarning(Owner owner) {
494	        String city = owner.getCity();
495	        if (city == null) {
496	            return false;
497	        }
498	        long othersInCity = this.clinicService.findAllOwners().stream()
499	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
500	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
501	            .count();
502	        return othersInCity >= CAPACITY_WARNING_THRESHOLD && othersInCity < CITY_CAPACITY;
503	    }
504	
505	    /**
506	     * The known disposable/throwaway email providers, mirroring the create endpoint's blocklist.
507	     * An email whose domain exactly matches one of these is rejected on create; the risk flag
508	     * instead catches domains that are merely <em>adjacent</em> to one of them (see
509	     * {@link #disposableAdjacentEmail(Owner)}).
510	     */
511	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS =
512	        java.util.Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
513	
514	    /**
515	     * The second-level labels of the known disposable providers (e.g. {@code mailinator} from
516	     * {@code mailinator.com}), used to recognise disposable-adjacent domains regardless of their
517	     * top-level domain or any subdomain in front.
518	     */
519	    private static final java.util.Set<String> DISPOSABLE_DOMAIN_LABELS = DISPOSABLE_EMAIL_DOMAINS.stream()
520	        .map(domain -> domain.substring(0, domain.lastIndexOf('.')))
521	        .collect(java.util.stream.Collectors.toUnmodifiableSet());
522	
523	    /**
524	     * Derives the owner's {@code riskFlag}: {@code true} when any of these hold, otherwise
525	     * {@code false}. The owner is a possible duplicate ({@code possibleDuplicate} is true), the
526	     * email domain is {@link #disposableAdjacentEmail(Owner) disposable-adjacent}, or the city is
527	     * over its soft capacity (the {@link #capacityWarning(Owner) capacity warning} is raised).
528	     */
529	    protected Boolean riskFlag(Owner owner) {
530	        return Boolean.TRUE.equals(owner.getPossibleDuplicate())
531	            || disposableAdjacentEmail(owner)
532	            || Boolean.TRUE.equals(capacityWarning(owner));
533	    }
534	
535	    /**
536	     * Whether the owner's email domain is <em>disposable-adjacent</em>: it shares a second-level
537	     * label with a known disposable provider (mailinator, tempmail, guerrillamail), so a subdomain
538	     * ({@code promo.mailinator.com}) or an alternate top-level domain ({@code tempmail.co}) that
539	     * slips past the create endpoint's exact-match blocklist is still recognised. Returns
540	     * {@code false} when the owner has no email or the domain shares no such label.
541	     */
542	    protected boolean disposableAdjacentEmail(Owner owner) {
543	        String email = owner.getEmail();
544	        if (email == null) {
545	            return false;
546	        }
547	        int at = email.lastIndexOf('@');
548	        if (at < 0 || at == email.length() - 1) {
549	            return false;
550	        }
551	        String domain = email.substring(at + 1).toLowerCase(java.util.Locale.ROOT);
552	        for (String label : domain.split("\\.")) {
553	            if (DISPOSABLE_DOMAIN_LABELS.contains(label)) {
554	                return true;
555	            }
556	        }
557	        return false;
558	    }
559	
560	    /**
561	     * Derives the owner's {@code salutation}: the owner's {@code title} and {@code lastName}
562	     * separated by a single space (e.g. {@code DR Franklin}), or just the {@code lastName} when no
563	     * title was supplied (a {@code null} or blank title).
564	     */
565	    protected String salutation(Owner owner) {
566	        String title = owner.getTitle();
567	        String lastName = owner.getLastName();
568	        if (title == null || title.isBlank()) {
569	            return lastName;
570	        }
571	        return title + " " + lastName;
572	    }
