23	/**
24	 * Derives an owner's consolidated identity key and the phonetic (Soundex) encoding it is built on.
25	 *
26	 * <p>The {@link #identityKey(String, String, String) identityKey} is the SHA-256, rendered as
27	 * lower-case hex, of the fixed {@value #VERSION_TAG} version tag, the owner's normalized telephone,
28	 * lower-cased email and the {@link #soundex(String) Soundex} of its last name, joined with {@code
29	 * '|'} separators. It is the single key both the duplicate-detection check and the exposed {@code
30	 * identityKey} field are computed from, so the two never diverge.
31	 */
32	public final class IdentityKeys {
33	
34	    /**
35	     * The fixed version tag mixed into every version-2 identifier so no value produced under
36	     * version 1 is produced again.
37	     */
38	    public static final String VERSION_TAG = "V2";
39	
40	    private IdentityKeys() {
41	    }
42	
43	    /**
44	     * Derives an owner's {@code identityKey}: the lower-case hex SHA-256 of
45	     * {@code "V2" + '|' + normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}. A
46	     * {@code null} telephone or email contributes an empty segment; the last name is always
47	     * contributed via its {@link #soundex(String) Soundex} encoding (empty when the last name is
48	     * absent). The leading {@value #VERSION_TAG} version tag is the version-2 identity marker.
49	     *
50	     * @param telephone the owner's normalized (E.164) telephone, may be {@code null}
51	     * @param email     the owner's lower-cased email, may be {@code null}
52	     * @param lastName  the owner's last name, may be {@code null}
53	     * @return the 64-character lower-case hex identity key
54	     */
55	    public static String identityKey(String telephone, String email, String lastName) {
56	        String input = VERSION_TAG
57	            + "|" + (telephone == null ? "" : telephone)
58	            + "|" + (email == null ? "" : email)
59	            + "|" + soundex(lastName);
60	        try {
61	            byte[] digest = MessageDigest.getInstance("SHA-256")
62	                .digest(input.getBytes(StandardCharsets.UTF_8));
63	            StringBuilder hex = new StringBuilder(digest.length * 2);
64	            for (byte b : digest) {
65	                hex.append(String.format("%02x", b));
66	            }
67	            return hex.toString();
68	        } catch (NoSuchAlgorithmException ex) {
69	            throw new IllegalStateException("SHA-256 not available", ex);
70	        }
71	    }
72	
73	    /**
74	     * Computes the American Soundex code of a name: the retained first letter followed by up to
75	     * three digits encoding the following consonants (b,f,p,v-&gt;1; c,g,j,k,q,s,x,z-&gt;2; d,t-&gt;3;
76	     * l-&gt;4; m,n-&gt;5; r-&gt;6), zero-padded to four characters. Adjacent letters with the same
77	     * code collapse to one; vowels (and y) separate same-coded consonants, while h and w are
78	     * transparent and do not. A {@code null} or letter-free name yields an empty string.
79	     *
80	     * @param name the name to encode, may be {@code null}
81	     * @return the four-character Soundex code, or an empty string when there is no letter to encode
82	     */
83	    public static String soundex(String name) {
84	        if (name == null) {
85	            return "";
86	        }
87	        StringBuilder letters = new StringBuilder();
88	        for (int i = 0; i < name.length(); i++) {
89	            char c = name.charAt(i);
90	            if (Character.isLetter(c)) {
91	                letters.append(Character.toUpperCase(c));
92	            }
93	        }
94	        if (letters.length() == 0) {
95	            return "";
96	        }
97	        StringBuilder code = new StringBuilder();
98	        code.append(letters.charAt(0));
99	        char previousCode = mappingCode(letters.charAt(0));
100	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
101	            char letter = letters.charAt(i);
102	            if (letter == 'H' || letter == 'W') {
103	                // Transparent: does not separate same-coded consonants, does not reset the run.
104	                continue;
105	            }
106	            char mapped = mappingCode(letter);
107	            if (mapped == '0') {
108	                // A vowel (or y) separates otherwise-identical codes.
109	                previousCode = '0';
110	                continue;
111	            }
112	            if (mapped != previousCode) {
113	                code.append(mapped);
114	            }
115	            previousCode = mapped;
116	        }
117	        while (code.length() < 4) {
118	            code.append('0');
119	        }
120	        return code.toString();
121	    }
122	
123	    /**
124	     * Maps a single upper-case letter to its Soundex digit ('0' for vowels, y, h and w).
125	     */
126	    private static char mappingCode(char letter) {
127	        return switch (letter) {
128	            case 'B', 'F', 'P', 'V' -> '1';
129	            case 'C', 'G', 'J', 'K', 'Q', 'S', 'X', 'Z' -> '2';
130	            case 'D', 'T' -> '3';
131	            case 'L' -> '4';
132	            case 'M', 'N' -> '5';
133	            case 'R' -> '6';
134	            default -> '0';
135	        };
136	    }
137	}
